INSERT INTO heritages (id, code, name, name_en, slug, province, province_en, category, period, brief_desc, brief_desc_en, story, story_en, highlights, reference_source, status, qr_status, view_count, image_url, image_alt, map_x, map_y, map_area_name) VALUES
  ('e6b455d3-7f42-4e08-a332-23a6011a8a5d', 'DS-01', 'Quần thể di tích Cố đô Huế', 'Complex of Hue Monuments', 'ds-01', 'Thừa Thiên Huế', 'Thua Thien Hue', 'Di sản Văn hóa Thế giới', 'Triều Nguyễn (1802 – 1945)', 'Kinh đô phong kiến cuối cùng của Việt Nam với hệ thống thành quách, cung điện, lăng tẩm hoàng gia uy nghiêm soi bóng bên dòng Hương Giang.', 'The last imperial capital of Vietnam, boasting fortified citadels, regal palaces, and tombs beside the Perfume River.', 'Khởi dựng từ năm 1805 dưới triều vua Gia Long và hoàn thiện dưới thời Minh Mạng, Cố đô Huế là biểu tượng đỉnh cao của nền quy hoạch đô thị và kiến trúc triều đình Việt Nam thế kỷ XIX. Trải qua hơn một thế kỷ thăng trầm lịch sử và khói lửa chiến tranh, Kinh thành Huế cùng Hoàng thành và Tử Cấm Thành vẫn gìn giữ trọn vẹn tinh hoa phong thủy Á Đông — lấy núi Ngự Bình làm bình phong, cồn Hến và cồn Dã Viên làm tả thanh long, hữu bạch hổ. Nơi đây không chỉ là quần thể kiến trúc đồ sộ mà còn là bảo tàng sống lưu giữ hồn cốt văn hóa, lễ nhạc và tri thức cung đình của một vương triều đã khép lại trang sử phong kiến nước nhà.', 'Founded in 1805 under Emperor Gia Long, the Complex of Hue Monuments embodies the pinnacle of 19th-century Vietnamese royal architecture and urban geomancy. Standing along the Perfume River, its citadel, imperial palaces, and emperor mausoleums remain an authentic living archive of courtly rituals, philosophy, and classical arts.', '["Kiến trúc cung đình phương Đông kết hợp kỹ thuật phòng thủ phương Tây kiểu Vauban.","Hệ thống lăng tẩm các hoàng đế nhà Nguyễn hòa quyện hài hòa cùng cảnh quan thiên nhiên.","Di sản tư liệu phong phú với Nhã nhạc cung đình, Mộc bản và Châu bản triều Nguyễn."]'::jsonb, 'Trung tâm Bảo tồn Di tích Cố đô Huế & Hồ sơ UNESCO số 678', 'published'::heritage_status, 'active'::qr_status, 150, '/assets/heritage/verified/ds-01.png', 'Ngọ Môn.png', 50.0, 50.0, 'Đường Nguyễn Văn Bình'),
  ('dbb3f1c4-4673-4b65-abc2-7a93006a4e17', 'DS-02', 'Đô thị cổ Hội An', 'Hoi An Ancient Town', 'ds-02', 'Quảng Nam', 'Quang Nam', 'Di sản Văn hóa Thế giới', 'Thế kỷ XVI – XIX', 'Thương cảng quốc tế truyền thống Đông Nam Á được bảo tồn gần như nguyên vẹn với mái ngói âm dương rêu phong và đèn lồng lung linh.', 'An exceptionally well-preserved Southeast Asian commercial port dating from the 16th to the 19th centuries.', 'Từng là thương cảng quốc tế sầm uất bậc nhất khu vực Đàng Trong từ thế kỷ XVI, Hội An là điểm hẹn giao thương của những đội thuyền buôn từ Nhật Bản, Trung Hoa, Bồ Đào Nha và Hà Lan. Nhờ sự chuyển dòng tự nhiên của sông Thu Bồn làm luồng lạch cạn dần ở thế kỷ XIX, Hội An may mắn thoát khỏi làn sóng đô thị hóa hiện đại, giữ lại gần như nguyên vẹn mạng lưới đường phố bàn cờ hẹp, những ngôi nhà cổ lợp ngói âm dương, giếng nước cổ Bá Lễ và cây Chùa Cầu linh thiêng. Nơi đây là minh chứng sống động cho tinh thần cởi mở, bao dung và sức sống bền bỉ của văn hóa cư dân miền Trung qua nhiều thế kỷ.', 'Thriving as a vibrant maritime trading hub from the 16th to the 19th centuries, Hoi An uniquely preserved its grid layout, wooden row houses, and assembly halls. Its gentle pace, timber bridges, and lantern-lit alleys reflect centuries of peaceful international cultural synthesis.', '["Giao thoa văn hóa kiến trúc đặc sắc giữa Việt Nam, Nhật Bản, Trung Hoa và phương Tây.","Quần thể nhà phố cổ khung gỗ, tường vàng quét vôi truyền thống và ngói âm dương.","Không gian sinh hoạt văn hóa dân gian gắn liền với lễ hội đèn lồng và ẩm thực xứ Quảng."]'::jsonb, 'Trung tâm Quản lý Bảo tồn Di sản Văn hóa Hội An & UNESCO số 948', 'published'::heritage_status, 'active'::qr_status, 150, '/assets/heritage/verified/ds-02.jpg', 'Hoi An Ancient Town.jpg', 50.0, 50.0, 'Đường Nguyễn Văn Bình'),
  ('0c8d0f33-f990-4f20-a369-630e91ff9f27', 'DS-03', 'Khu đền tháp Mỹ Sơn', 'My Son Sanctuary', 'ds-03', 'Quảng Nam', 'Quang Nam', 'Di sản Văn hóa Thế giới', 'Thế kỷ IV – XIII (Vương quốc Chămpa)', 'Thánh địa tôn giáo linh thiêng của nền văn minh Chămpa ẩn mình trong thung lũng khép kín, nổi tiếng với nghệ thuật xây gạch không mạch vữa.', 'A religious valley sanctuary of the ancient Champa civilization, famous for mortarless brick architecture and sandstone reliefs.', 'Nằm ẩn mình giữa thung lũng lòng chảo đường kính chừng hai cây số được bao bọc bởi núi Chúa hùng vĩ, Mỹ Sơn từng là trung tâm cúng tế linh thiêng nhất của các triều vua Chămpa suốt gần một ngàn năm. Hơn 70 công trình đền tháp bằng gạch đỏ rực đứng uy nghiêm giữa màu xanh đại ngàn, được xây dựng theo kỹ thuật ghép gạch kín khít thần kỳ mà khoa học hiện đại vẫn miệt mài nghiên cứu. Dù bom đạn chiến tranh đã hủy hoại nhiều cụm tháp, các phế tích trầm mặc còn lại vẫn toát lên vẻ đẹp siêu việt của nghệ thuật điêu khắc hoa văn dây leo, thần hộ pháp Dvarapala và vũ nữ Apsara mềm mại.', 'Set within a secluded amphitheater valley presided over by sacred Cat''s Tooth Mountain, My Son was the spiritual epicenter of the Champa kingdom for nearly a millennium. Its red-brick tower temples, carved directly into living brick, stand as poignant monuments of engineering mastery and Hindu-Buddhist art.', '["Tuyệt kỹ xây dựng tháp bằng gạch nung kết dính bí ẩn không để lộ mạch vữa.","Hệ thống điêu khắc đá sa thạch mang đậm dấu ấn Ấn Độ giáo tôn vinh thần Shiva.","Bằng chứng vật chất độc nhất về một nền văn minh bản địa phát triển rực rỡ suốt cả thiên niên kỷ."]'::jsonb, 'Ban Quản lý Di sản Văn hóa Mỹ Sơn & Hồ sơ UNESCO số 949', 'published'::heritage_status, 'active'::qr_status, 150, '/assets/heritage/verified/ds-03.jpg', 'My Son Sanctuary, Vietnam, 2017 (52416000869).jpg', 50.0, 50.0, 'Đường Nguyễn Văn Bình'),
  ('d98f008f-0d5d-4b7c-a799-eebbc66963fb', 'DS-04', 'Khu trung tâm Hoàng thành Thăng Long', 'Central Sector of the Imperial Citadel of Thang Long', 'ds-04', 'Hà Nội', 'Hanoi', 'Di sản Văn hóa Thế giới', 'Khởi lập năm 1010 (Lý – Trần – Lê – Nguyễn)', 'Trung tâm quyền lực chính trị liên tục suốt 13 thế kỷ của các triều đại phong kiến Đại Việt, chứa đựng tầng văn hóa khảo cổ vô giá.', 'The continuous political power hub of Dai Viet dynasties across 13 centuries, featuring priceless archaeological strata.', 'Mùa thu năm Canh Tuất 1010, vua Lý Thái Tổ ban Chiếu dời đô từ Hoa Lư về thành Đại La, mở ra trang sử rực rỡ của kinh đô Thăng Long nghìn năm văn hiến. Trải qua hơn một nghìn năm với các vương triều Lý, Trần, Lê, Mạc, Nguyễn, mảnh đất này luôn giữ vị thế trái tim quyền lực của nước Đại Việt. Những cuộc khai quật khảo cổ học tại 18 Hoàng Diệu đã làm phát lộ các tầng văn hóa chồng xếp lên nhau nguyên vẹn, từ giếng nước gạch hoa, ngói rồng men xanh thời Lý đến dấu tích nền Điện Kính Thiên thời Hậu Lê. Hoàng thành Thăng Long là biểu tượng trường tồn của độc lập dân tộc và bản lĩnh văn hiến Việt Nam.', 'Established in 1010 when King Ly Thai To moved the capital to Thang Long, this site remained the seat of imperial administrative power for consecutive dynasties. Archeological findings at 18 Hoang Dieu prove an unbroken civilizational continuum spanning over a thousand years.', '["Tính kế thừa và liên tục quyền lực chính trị hiếm có trong lịch sử thế giới.","Tầng văn hóa khảo cổ dày đặc phát lộ dấu tích cung điện từ thời Tiền Thăng Long đến hiện đại.","Các di tích nổi bật: Cột cờ Hà Nội, Đoan Môn, Điện Kính Thiên, Hậu Lâu và Bắc Môn."]'::jsonb, 'Trung tâm Bảo tồn Di sản Thăng Long - Hà Nội & Hồ sơ UNESCO số 1328', 'published'::heritage_status, 'active'::qr_status, 150, '/assets/heritage/verified/ds-04.jpg', 'Doan Mon Gate 2.jpg', 50.0, 50.0, 'Đường Nguyễn Văn Bình'),
  ('22a1475e-29aa-47c9-a13c-60bbc2dec7ad', 'DS-05', 'Thành nhà Hồ', 'Citadel of the Ho Dynasty', 'ds-05', 'Thanh Hóa', 'Thanh Hoa', 'Di sản Văn hóa Thế giới', 'Xây dựng năm 1397 (Nhà Hồ)', 'Tòa thành kiên cố xây hoàn toàn bằng những khối đá xanh khổng lồ đẽo gọt chuẩn xác, kiệt tác kiến trúc quân sự độc nhất vô nhị ở Đông Nam Á.', 'A stone-block fortress built in 1397 using massive limestone blocks, standing as an exceptional military engineering masterpiece.', 'Được Hồ Quý Ly cho khởi công xây dựng vào mùa xuân năm Đinh Sửu 1397 với tên gọi Tây Đô chỉ trong vỏn vẹn ba tháng, Thành nhà Hồ là hiện tượng kỳ vĩ trong lịch sử kiến trúc quân sự thế giới. Toàn bộ bốn bức tường thành và bốn vòm cổng uy nghi đều được ghép bằng những tảng đá vôi xanh nguyên khối khổng lồ, được ghè đẽo vuông vức và xếp khít khao không cần đến bất kỳ loại vữa kết dính nào. Dưới thời tiết khắc nghiệt miền Trung suốt hơn sáu thế kỷ, cổng vòm Nam của thành vẫn đứng sừng sững uy nghi, chứng minh trí tuệ siêu phàm và sức lao động phi thường của tiền nhân Đại Việt.', 'Constructed in just three months in 1397 under Ho Quy Ly, this colossal stone citadel was fashioned entirely from massive limestone blocks fitted together without cement. Its monumental arched southern gates have endured six centuries as a testament to exceptional Vietnamese stone-masonry.', '["Công trình thành đá cổ duy nhất còn lại ở Đông Nam Á được lắp ghép không dùng chất kết dính.","Khối lượng đá xanh đồ sộ nặng từ 10 đến 26 tấn được vận chuyển và lắp ráp chuẩn xác tuyệt đối.","Sự kết hợp tinh tế giữa quy phạm phong thủy Nho giáo truyền thống và kỹ nghệ công sự phòng thủ."]'::jsonb, 'Ban Quản lý Di tích Thành Nhà Hồ & Hồ sơ UNESCO số 1358', 'published'::heritage_status, 'active'::qr_status, 150, '/assets/heritage/verified/ds-05.jpg', 'Tay Do castle South gate.JPG', 50.0, 50.0, 'Đường Nguyễn Văn Bình'),
  ('bde1a23a-8af6-461d-adca-3a0d33b64f28', 'DS-06', 'Quần thể danh thắng Tràng An', 'Trang An Landscape Complex', 'ds-06', 'Ninh Bình', 'Ninh Binh', 'Di sản Thế giới Hỗn hợp (Văn hóa & Thiên nhiên)', 'Địa chất karst 250 triệu năm & Di chỉ tiền sử 30.000 năm', 'Di sản thế giới kép đầu tiên tại Đông Nam Á, nơi giao hòa giữa tháp karst nhiệt đới ngập nước tuyệt mỹ và dấu vết người tiền sử.', 'Southeast Asia''s first dual mixed World Heritage Site, blending spectacular flooded karst towers with 30,000 years of human evolution.', 'Tràng An là bản hòa ca tráng lệ giữa thiên nhiên kỳ vĩ và chiều sâu lịch sử dân tộc. Cảnh quan nơi đây gồm các dãy tháp đá vôi dựng đứng soi bóng xuống mặt nước trong vắt, kết nối qua hệ thống 48 hang động xuyên thủy kỳ ảo như hang Sáng, hang Tối, hang Nấu Rượu. Bên trong những mái đá thâm u, các nhà khảo cổ đã tìm thấy vỏ nhuyễn thể, công cụ đá chứng minh con người tiền sử đã liên tục sinh sống và thích ứng bền bỉ qua các đợt biển tiến, biển thoái từ hơn 30.000 năm trước. Nơi đây cũng từng là kinh đô Hoa Lư vững chắc bảo vệ non sông thời Đinh - Tiền Lê thế kỷ thứ X.', 'Trang An presents a breathtaking landscape of sheer karst towers rising above quiet flooded valleys. Archaeological excavations across cave shelters here unearthed invaluable evidence of human prehistoric settlement adapting to changing sea levels over 30,000 years, beside being the historical cradle of ancient Hoa Lu.', '["Di sản hỗn hợp văn hóa và thiên nhiên duy nhất được UNESCO công nhận tại Việt Nam.","Cảnh quan karst tháp chuông ngoạn mục đan xen mạng lưới hang động và thung nước nguyên sơ.","Hồ sơ khảo cổ lưu giữ bằng chứng cư trú và thích ứng biến đổi khí hậu của người tiền sử."]'::jsonb, 'Ban Quản lý Quần thể Danh thắng Tràng An & UNESCO số 1438', 'published'::heritage_status, 'active'::qr_status, 150, '/assets/heritage/verified/ds-06.jpg', 'Trang An, Ninh Binh.jpg', 50.0, 50.0, 'Đường Nguyễn Văn Bình'),
  ('3a7c495b-4dd9-4bac-aae6-f7e762970c50', 'DS-07', 'Vườn quốc gia Phong Nha – Kẻ Bàng', 'Phong Nha – Ke Bang National Park', 'ds-07', 'Quảng Bình', 'Quang Binh', 'Di sản Thiên nhiên Thế giới', 'Quá trình kiến tạo địa chất karst hơn 400 triệu năm', 'Vương quốc hang động thế giới sở hữu khối karst cổ nhất châu Á cùng hang Sơn Đoòng — hang động tự nhiên lớn nhất hành tinh.', 'The world''s cave kingdom with Asia''s oldest karst system and Son Doong, the largest natural cave on Earth.', 'Được mệnh danh là trái tim của di sản địa chất Việt Nam, Phong Nha – Kẻ Bàng bảo tồn một bảo tàng địa chất sống động được hình thành từ kỷ Cổ sinh cách đây hơn 400 triệu năm. Nơi đây ẩn giấu quần thể hang động tráng lệ bậc nhất trái đất, từ động Thiên Đường lung linh muôn sắc thạch nhũ, động Phong Nha với dòng sông ngầm dài nhất, đến hang Sơn Đoòng với thể tích khổng lồ đủ sức chứa cả một dãy phố cao tầng New York bên trong. Thảm rừng nhiệt đới nguyên sinh bạt ngàn bao phủ các dãy núi đá vôi cũng là ngôi nhà cư trú an lành của hàng ngàn loài động thực vật quý hiếm nằm trong Sách Đỏ.', 'Representing more than 400 million years of Earth history, Phong Nha – Ke Bang is celebrated globally as the ultimate kingdom of caves. Housing Hang Son Doong and underground rivers flowing beneath undisturbed primary rainforests, it protects unparalleled karst beauty and rich endemic wildlife.', '["Hệ thống hang động kỳ vĩ dài hơn 300km với các sông ngầm, thạch nhũ và hố sụt khổng lồ.","Khối đá vôi cổ xưa nhất châu Á trải qua nhiều thời kỳ biến dạng kiến tạo phức tạp.","Khu hệ sinh thái rừng nhiệt đới nguyên sinh có độ đa dạng sinh học đặc biệt cao."]'::jsonb, 'Ban Quản lý Vườn Quốc gia Phong Nha - Kẻ Bàng & UNESCO số 95', 'published'::heritage_status, 'active'::qr_status, 150, '/assets/heritage/verified/ds-07.jpg', 'PhongNhaCave.jpg', 50.0, 50.0, 'Đường Nguyễn Văn Bình'),
  ('9c035a5d-9ec0-4117-a6c3-4711db9d863a', 'DS-08', 'Vịnh Hạ Long – Quần đảo Cát Bà', 'Ha Long Bay – Cat Ba Archipelago', 'ds-08', 'Quảng Ninh / Hải Phòng', 'Quang Ninh / Hai Phong', 'Di sản Thiên nhiên Thế giới', 'Tiến hóa địa chất karst ngập biển 500 triệu năm', 'Kỳ quan thiên nhiên thế giới với hàng ngàn hòn đảo đá vôi xanh ngắt nổi bật giữa mặt biển phẳng lặng như tấm gương khổng lồ.', 'A magnificent marine world wonder comprising thousands of dramatic limestone towers emerging from emerald sea waters.', 'Gắn liền với huyền tích rồng mẹ cùng đàn rồng con hạ phàm phun châu nhả ngọc tạo thành hàng ngàn đảo đá ngăn chặn giặc ngoại xâm, Vịnh Hạ Long và Quần đảo Cát Bà là tuyệt tác kỳ vĩ của thiên nhiên nhiệt đới. Qua hàng triệu năm chịu tác động của sóng biển và gió mùa, các khối núi đá vôi vươn thẳng từ lòng đại dương đã tạo nên các vòm hang kỳ thú như hang Đầu Gỗ, động Thiên Cung và hồ Ba Hầm. Năm 2023, UNESCO đã chính thức mở rộng ranh giới di sản sang Quần đảo Cát Bà, khẳng định giá trị toàn cầu nguyên vẹn của kỳ quan sinh thái biển đảo số một nước ta.', 'Entwined with the legend of the Mother Dragon descending to protect the realm, Ha Long Bay and Cat Ba Archipelago represent nature''s greatest maritime sculpture. Thousands of towering limestone pillars and turquoise bays create a tranquil sanctuary of exceptional aesthetic and geological worth.', '["Hình mẫu xuất sắc nhất thế giới về cảnh quan karst chìm ngập trong biển nhiệt đới.","Quần tụ hơn 2.600 hòn đảo lớn nhỏ mang hình thù sống động như rồng thiêng hạ cánh.","Hệ sinh thái biển đảo phong phú với rừng ngập mặn, rạn san hô và loài Voọc Cát Bà cực kỳ quý hiếm."]'::jsonb, 'Ban Quản lý Vịnh Hạ Long & Hồ sơ UNESCO số 672 bis (Mở rộng 2023)', 'published'::heritage_status, 'active'::qr_status, 150, '/assets/heritage/verified/ds-08.jpg', 'Ha Long Bay - Bahía de Ha Long.JPG', 50.0, 50.0, 'Đường Nguyễn Văn Bình'),
  ('71e08a20-374b-4115-a5ef-f30d7199063d', 'DS-09', 'Khu di tích Chủ tịch Hồ Chí Minh tại Phủ Chủ tịch', 'Presidential Palace Historical Site', 'ds-09', 'Hà Nội', 'Hanoi', 'Di tích Lịch sử - Lưu niệm Quốc gia', 'Thời kỳ 1954 – 1969', 'Không gian sống và làm việc suốt 15 năm cuối đời của Chủ tịch Hồ Chí Minh, tiêu biểu với ngôi Nhà sàn gỗ mộc mạc bên bờ ao cá.', 'The modest residence and workspace where President Ho Chi Minh lived and worked from 1954 until 1969.', 'Từ năm 1954 đến khi Người qua đời vào mùa thu năm 1969, Chủ tịch Hồ Chí Minh đã chọn sống trong một căn nhà nhỏ đơn sơ thay vì tòa dinh thự Phủ Toàn quyền lộng lẫy kế bên. Ngôi nhà sàn bằng gỗ hai tầng thoáng đãng hướng ra ao cá, xung quanh là hàng dâm bụt đỏ, hàng xoài miền Nam và những cây vú sữa đồng bào gửi tặng. Tại góc bàn làm việc nhìn ra mặt nước phẳng lặng, Người đã cùng Trung ương hoạch định đường lối kháng chiến cứu nước, soạn thảo bản Di chúc lịch sử thiêng liêng. Nơi đây mãi là biểu tượng cao đẹp của đạo đức cách mạng và tinh thần tận tụy vì nhân dân.', 'Spanning from 1954 to 1969, President Ho Chi Minh chose to reside in a humble wooden stilt house rather than the opulent colonial palace. Surrounded by orchards, southern mango trees, and an open fish pond, this peaceful sanctuary was where pivotal decisions shaping Vietnam''s modern history were forged.', '["Nơi lưu giữ trọn vẹn phong cách sống thanh bạch, giản dị của vị lãnh tụ kính yêu.","Ngôi nhà sàn gỗ kiến trúc dân tộc Thái nằm giữa vườn cây xum xuê và ao cá Bác Hồ.","Bộ sưu tập hàng ngàn tài liệu, hiện vật và những tác phẩm tư tưởng bất hủ thời đại."]'::jsonb, 'Khu Di tích Chủ tịch Hồ Chí Minh tại Phủ Chủ tịch & Bộ Văn hóa, Thể thao và Du lịch', 'published'::heritage_status, 'active'::qr_status, 150, '/assets/heritage/verified/ds-09.jpg', 'Ho Chi Minh House 3012017573 19ef7d0d3c.jpg', 50.0, 50.0, 'Đường Nguyễn Văn Bình'),
  ('6b450a5c-00f4-4f2b-abfb-06655bcdf713', 'DS-10', 'Di tích lịch sử Địa đạo Củ Chi', 'Cu Chi Tunnels Historical Relic', 'ds-10', 'TP. Hồ Chí Minh', 'Ho Chi Minh City', 'Di tích Lịch sử Quân sự Quốc gia', 'Giai đoạn kháng chiến 1946 – 1968', 'Mạng lưới công sự ngầm dài hơn 250km được ví như “thành phố trong lòng đất”, minh chứng cho ý chí kiên cường và nghệ thuật chiến tranh nhân dân.', 'A subterranean labyrinth extending over 250km dug by hand, acclaimed worldwide as a subterranean marvel of human resilience.', 'Được mệnh danh là “vùng đất thép thành đồng”, Địa đạo Củ Chi được đào hoàn toàn bằng sức người với dụng cụ thô sơ suốt những năm tháng kháng chiến chống giặc ngoại xâm ác liệt. Mạng lưới đường hầm chằng chịt dài trên 250km xuyên sâu dưới lòng đất từ 3 đến 12 mét, chống chịu được đạn pháo và bom hạng nặng. Dưới lòng đất tối tăm và thiếu dưỡng khí, các chiến sĩ và đồng bào Củ Chi vẫn sinh hoạt, chữa bệnh, nấu nướng bằng bếp Hoàng Cầm giấu khói và tổ chức các cuộc tiến công quyết định. Địa đạo Củ Chi ngày nay là điểm đến lịch sử nổi tiếng toàn cầu, thu hút hàng triệu du khách đến chiêm ngưỡng ý chí kiên cường của con người Việt Nam.', 'Chiseled entirely by hand into hard laterite earth over decades of resistance, the Cu Chi tunnels stretch over 250 kilometers underground. Functioning as living quarters, hospitals, weapon workshops, and command posts, it stands today as an internationally recognized monument to indomitable human spirit.', '["Hệ thống đường hầm nhiều tầng sâu trong lòng đất đất sét ong với các cửa nắp ngụy trang bí mật.","Đầy đủ công năng sinh hoạt chiến đấu: phòng hội họp, bếp Hoàng Cầm không khói, bệnh xá và giếng nước.","Kỳ tích quân sự độc đáo khẳng định sức mạnh đoàn kết và ý chí bất khuất của quân dân Nam Bộ."]'::jsonb, 'Ban Quản lý Khu Di tích Lịch sử Địa đạo Củ Chi & UBND TP. Hồ Chí Minh', 'published'::heritage_status, 'active'::qr_status, 150, '/assets/heritage/verified/ds-10.jpg', 'Cu Chi Tunnel.jpg', 50.0, 50.0, 'Đường Nguyễn Văn Bình')
